const noodle='https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80';
const soup='https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80';
const drink='https://images.unsplash.com/photo-1556679343-c7306c1976bc?auto=format&fit=crop&w=800&q=80';
const menu=[{name:'Mie Ayam Original',category:'mie',price:15000,description:'Mie dengan topping ayam berbumbu, sayuran, dan kuah hangat.',image:noodle,tag:'KLASIK'},{name:'Mie Ayam Bakso',category:'mie',price:20000,description:'Mie ayam dan bakso dalam satu mangkuk. Komplet untuk rasa laparmu.',image:noodle,tag:'REKOMENDASI KONSEP'},{name:'Bakso Kuah',category:'bakso',price:18000,description:'Bakso dengan kuah gurih dan pelengkap untuk dinikmati hangat.',image:soup,tag:'HANGAT & GURIH'},{name:'Es Teh',category:'minuman',price:5000,description:'Teh dingin untuk menemani semangkuk menu pilihanmu.',image:drink,tag:'SEGAR'}];
function render(category='semua'){document.querySelector('#menu-grid').replaceChildren(...menu.filter(item=>category==='semua'||item.category===category).map(item=>{const article=document.createElement('article');article.className='menu-card';article.innerHTML=`<div class="food-image"><img src="${item.image}" alt="Foto ilustrasi ${item.name}, bukan foto produk resmi" loading="lazy"><span class="tag">${item.tag}</span></div><h3>${item.name}</h3><p>${item.description}</p><div class="price"><span>${new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(item.price)}</span><a href="#pesan" aria-label="Informasi pemesanan ${item.name}">↗</a></div>`;return article}))}render();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button))});render(button.dataset.filter)}));
document.querySelector('[data-interest]').addEventListener('click',()=>{document.querySelector('#topic').value='Kemitraan';document.querySelector('#pesan').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#name').focus({preventScroll:true})});
let messageUrl;document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const name=document.querySelector('#name'),message=document.querySelector('#message');if(!name.value.trim()||!message.value.trim()){(name.value.trim()?message:name).setCustomValidity('Isi bagian ini dengan teks.');event.target.reportValidity();return}if(messageUrl)URL.revokeObjectURL(messageUrl);messageUrl=URL.createObjectURL(new Blob([`Nama: ${name.value.trim()}\nTopik: ${document.querySelector('#topic').value}\n\n${message.value.trim()}`],{type:'text/plain;charset=utf-8'}));document.querySelector('#download').href=messageUrl;document.querySelector('#form-result').hidden=false});document.querySelectorAll('input,textarea').forEach(input=>input.addEventListener('input',()=>{input.setCustomValidity('');document.querySelector('#form-result').hidden=true}));document.querySelector('#year').textContent=new Date().getFullYear();
